function maxSumSubarray(nums, k) {
  let windowSum = 0;
  for (let i = 0; i < k; i++) windowSum += nums[i]; // first window
  let best = windowSum;
  for (let right = k; right < nums.length; right++) {
    windowSum += nums[right] - nums[right - k]; // add the new, drop the oldest
    best = Math.max(best, windowSum);
  }
  return best;
}

public int maxSumSubarray(int[] nums, int k) {
    int windowSum = 0;
    for (int i = 0; i < k; i++) windowSum += nums[i]; // first window
    int best = windowSum;
    for (int right = k; right < nums.length; right++) {
        windowSum += nums[right] - nums[right - k]; // add the new, drop the oldest
        best = Math.max(best, windowSum);
    }
    return best;
}

function maxProfit(prices) {
  let buy = 0; // left edge: cheapest day seen so far
  let best = 0;
  for (let sell = 1; sell < prices.length; sell++) {
    if (prices[sell] < prices[buy]) {
      buy = sell; // cheaper day found: restart the window here
    } else {
      best = Math.max(best, prices[sell] - prices[buy]); // try selling today
    }
  }
  return best;
}

