            left = lastSeen.get(c) + 1; // jump past the previous copy
        }
        lastSeen.put(c, right);
        best = Math.max(best, right - left + 1);
    }
    return best;
}

function characterReplacement(s, k) {
  const count = new Map(); // char -> count inside the window
  let left = 0;
  let maxFreq = 0; // highest count of a single char seen so far
  let best = 0;
  for (let right = 0; right < s.length; right++) {
    const c = s[right];
    count.set(c, (count.get(c) || 0) + 1);
    maxFreq = Math.max(maxFreq, count.get(c));
    while (right - left + 1 - maxFreq > k) { // too many chars to replace
      count.set(s[left], count.get(s[left]) - 1);
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

public int characterReplacement(String s, int k) {
    int[] count = new int[26]; // 'A'..'Z' -> count inside the window
    int left = 0, maxFreq = 0, best = 0;
    for (int right = 0; right < s.length(); right++) {
        int c = s.charAt(right) - 'A';
        maxFreq = Math.max(maxFreq, ++count[c]);
        while (right - left + 1 - maxFreq > k) { // too many chars to replace
            count[s.charAt(left) - 'A']--;
            left++;
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}

function checkInclusion(s1, s2) {
  const m = s1.length;
  if (m > s2.length) return false;
  const need = new Map(); // char -> how many more the window still needs
  for (const c of s1) need.set(c, (need.get(c) || 0) + 1);
  let missing = m; // chars of s1 not yet covered by the window
  for (let right = 0; right < s2.length; right++) {
    const c = s2[right];
    if ((need.get(c) || 0) > 0) missing--; // c was needed
    need.set(c, (need.get(c) || 0) - 1);
    const left = right - m; // index that just fell out of the window
    if (left >= 0) {
      const out = s2[left];
      need.set(out, need.get(out) + 1);
      if (need.get(out) > 0) missing++; // we lost a needed char
    }
    if (missing === 0) return true; // window is a permutation of s1
  }
  return false;
}

