function maxSlidingWindow(nums, k) {
  const dq = []; // indices; their values decrease from front to back
  let head = 0; // dq[head] is the front (avoids O(n) shift())
  const result = [];
  for (let i = 0; i < nums.length; i++) {
    if (head < dq.length && dq[head] <= i - k) head++; // front left the window
    while (head < dq.length && nums[dq[dq.length - 1]] <= nums[i]) {
      dq.pop(); // smaller values can never be a maximum again
    }
    dq.push(i);
    if (i >= k - 1) result.push(nums[dq[head]]); // front holds the max
  }
  return result;
}

from collections import deque


def max_sliding_window(nums, k):
    dq = deque()  # indices; their values decrease from front to back
    result = []
    for i, x in enumerate(nums):
        if dq and dq[0] <= i - k:
            dq.popleft()  # front left the window
        while dq and nums[dq[-1]] <= x:
            dq.pop()  # smaller values can never be a maximum again
        dq.append(i)
        if i >= k - 1:
            result.append(nums[dq[0]])  # front holds the max
    return result

public int[] maxSlidingWindow(int[] nums, int k) {
    Deque<Integer> dq = new ArrayDeque<>(); // indices, values decreasing front -> back
    int[] result = new int[nums.length - k + 1];
    for (int i = 0; i < nums.length; i++) {
        if (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst(); // front left the window
        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) {
            dq.pollLast(); // smaller values can never be a maximum again
        }
        dq.offerLast(i);
        if (i >= k - 1) result[i - k + 1] = nums[dq.peekFirst()]; // front holds the max
    }
    return result;
}

